    run_id uuid DEFAULT gen_random_uuid() NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    stopped_at timestamp with time zone,
    heartbeat_ts timestamp with time zone DEFAULT now() NOT NULL,
    version_sha text NOT NULL,
    host text NOT NULL,
    pid integer NOT NULL
);


COMMENT ON TABLE dispatcher.runs IS 'One row per daemon boot. Latest row is the active lease.';


COMMENT ON COLUMN dispatcher.runs.heartbeat_ts IS 'Daemon updates every tick. CloudWatch alarm pages if stale > 5min.';


COMMENT ON COLUMN dispatcher.runs.version_sha IS 'Git SHA of the daemon build; supports forensic questions after a crash.';


CREATE TABLE dispatcher.terminal_outcomes (
    outcome_id bigint NOT NULL,
    agent_id uuid,
    issue_number integer,
    status text NOT NULL,
    ended_at timestamp with time zone DEFAULT now() NOT NULL
);


COMMENT ON TABLE dispatcher.terminal_outcomes IS 'Append-only ring buffer of terminal agent outcomes. Scanned by ``_evaluate_circuit_breaker`` over a rolling window to decide whether to auto-pause ``concurrency_cap``. Issue #2860.';


COMMENT ON COLUMN dispatcher.terminal_outcomes.agent_id IS 'Nullable — synthetic test inputs may have no agent row. Production writes always carry this.';


COMMENT ON COLUMN dispatcher.terminal_outcomes.status IS 'Free-form text (succeeded | failed | crashed | plan_blocked | needs_review | ...). Classifier in daemon decides which count as bad.';


CREATE SEQUENCE dispatcher.terminal_outcomes_outcome_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE dispatcher.terminal_outcomes_outcome_id_seq OWNED BY dispatcher.terminal_outcomes.outcome_id;


CREATE TABLE dispatcher.unrecognized_diagnoser_actions (
    id bigint NOT NULL,
    diagnosis_id bigint NOT NULL,
    action_name text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL
);


COMMENT ON TABLE dispatcher.unrecognized_diagnoser_actions IS 'Diagnoser actions the daemon did not recognize. Operator reviews periodically; 5+ instances of a new action is signal to implement a handler. See issue #3032.';


COMMENT ON COLUMN dispatcher.unrecognized_diagnoser_actions.action_name IS 'The action string as emitted by the diagnoser (e.g. "split_task"). Not constrained — anything the LLM proposed that was not in the known set lands here.';


COMMENT ON COLUMN dispatcher.unrecognized_diagnoser_actions.payload IS 'The full recommendation dict (action + reasoning + any payload fields the LLM proposed) serialized as JSONB. Lets a future handler implementer see the proposed shape without replaying the diagnosis.';


CREATE SEQUENCE dispatcher.unrecognized_diagnoser_actions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE dispatcher.unrecognized_diagnoser_actions_id_seq OWNED BY dispatcher.unrecognized_diagnoser_actions.id;


CREATE TABLE public.alert_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subscription_id uuid NOT NULL,
    document_id uuid,
    ruling_id uuid,
    triggered_at timestamp with time zone DEFAULT now() NOT NULL,
    included_in_digest_at timestamp with time zone,
    digest_sent boolean DEFAULT false NOT NULL
);


CREATE TABLE public.alert_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    alert_type public.alert_type NOT NULL,
    filters jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.refresh_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    token_hash text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    email_verified boolean DEFAULT false NOT NULL,
    password_hash text,
    display_name text,
    role text DEFAULT 'user'::text NOT NULL,
    api_key text,
    ai_budget_daily integer DEFAULT 20 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    last_login_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    google_id text
);


CREATE TABLE staging.captures (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    court_id uuid NOT NULL,
    scraper_id text NOT NULL,
    source_url text NOT NULL,
    raw_content text NOT NULL,
    raw_content_type text NOT NULL,
    content_hash text NOT NULL,
    capture_metadata jsonb,
    captured_at timestamp with time zone NOT NULL,
    validation_status public.validation_status DEFAULT 'pending'::public.validation_status NOT NULL,
    validation_notes text,
    validated_at timestamp with time zone,
    validated_by text,
    promoted_at timestamp with time zone,
    promoted_document_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE staging.ruled_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    capture_id uuid NOT NULL,
    court_id uuid NOT NULL,
    case_number_raw text,
    judge_name_raw text,
    department_raw text,
    hearing_date date,
    ruling_text text,
    motion_type_raw text,
    outcome_raw text,
    parsed_metadata jsonb,
    validation_status public.validation_status DEFAULT 'pending'::public.validation_status NOT NULL,
    validation_notes text,
    validated_at timestamp with time zone,
    promoted_at timestamp with time zone,
    promoted_ruling_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE telemetry.data_quality_metrics (
    id bigint NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    county text NOT NULL,
    metric_name text NOT NULL,
    metric_value numeric NOT NULL,
    metadata jsonb
);


CREATE SEQUENCE telemetry.data_quality_metrics_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE telemetry.data_quality_metrics_id_seq OWNED BY telemetry.data_quality_metrics.id;


CREATE TABLE telemetry.scraper_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scraper_id text NOT NULL,
    court_id uuid,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    status text NOT NULL,
    records_captured integer DEFAULT 0 NOT NULL,
    records_failed integer DEFAULT 0 NOT NULL,
    error_message text,
    error_details jsonb,
    response_time_ms integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


CREATE TABLE telemetry.validation_results (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id uuid NOT NULL,
    ruling_id uuid,
    result text NOT NULL,
    reason text,
    model text,
    input_tokens integer,
    output_tokens integer,
    latency_ms integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT validation_results_result_check CHECK ((result = ANY (ARRAY['pass'::text, 'flag'::text, 'fail'::text, 'error'::text])))
);


COMMENT ON TABLE telemetry.validation_results IS 'LLM validation outcomes for ingested documents. One row per validation check.';


COMMENT ON COLUMN telemetry.validation_results.result IS 'Validation outcome: pass (write normally), flag (write + review), fail (skip write), error (LLM call failed).';


COMMENT ON COLUMN telemetry.validation_results.reason IS 'Human-readable reason for flag/fail results. NULL for pass results.';


COMMENT ON COLUMN telemetry.validation_results.model IS 'LLM model used for validation (e.g. claude-haiku-4-5-20251001).';


COMMENT ON COLUMN telemetry.validation_results.latency_ms IS 'Wall-clock time for the validation LLM call in milliseconds.';


