ALTER TABLE ONLY dispatcher.failures
    ADD CONSTRAINT failures_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES dispatcher.agents(agent_id);


ALTER TABLE ONLY dispatcher.phase_outputs
    ADD CONSTRAINT phase_outputs_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES dispatcher.agents(agent_id);


ALTER TABLE ONLY dispatcher.phase_outputs
    ADD CONSTRAINT phase_outputs_patch_id_fkey FOREIGN KEY (patch_id) REFERENCES dispatcher.ralph_patches(patch_id) ON DELETE SET NULL;


ALTER TABLE ONLY dispatcher.phase_transitions
    ADD CONSTRAINT phase_transitions_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES dispatcher.agents(agent_id);


ALTER TABLE ONLY dispatcher.queue_snapshots
    ADD CONSTRAINT queue_snapshots_run_id_fkey FOREIGN KEY (run_id) REFERENCES dispatcher.runs(run_id) ON DELETE CASCADE;


ALTER TABLE ONLY dispatcher.ralph_patches
    ADD CONSTRAINT ralph_patches_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES dispatcher.agents(agent_id);


ALTER TABLE ONLY dispatcher.retry_markers
    ADD CONSTRAINT retry_markers_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES dispatcher.agents(agent_id);


ALTER TABLE ONLY dispatcher.unrecognized_diagnoser_actions
    ADD CONSTRAINT unrecognized_diagnoser_actions_diagnosis_id_fkey FOREIGN KEY (diagnosis_id) REFERENCES dispatcher.diagnoses(diagnosis_id);


ALTER TABLE ONLY public.alert_events
    ADD CONSTRAINT alert_events_document_id_fkey FOREIGN KEY (document_id) REFERENCES derived.documents(id);


ALTER TABLE ONLY public.alert_events
    ADD CONSTRAINT alert_events_ruling_id_fkey FOREIGN KEY (ruling_id) REFERENCES derived.rulings(id);


ALTER TABLE ONLY public.alert_events
    ADD CONSTRAINT alert_events_subscription_id_fkey FOREIGN KEY (subscription_id) REFERENCES public.alert_subscriptions(id) ON DELETE CASCADE;


ALTER TABLE ONLY public.alert_subscriptions
    ADD CONSTRAINT alert_subscriptions_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;


ALTER TABLE ONLY public.refresh_tokens
    ADD CONSTRAINT refresh_tokens_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;


ALTER TABLE ONLY staging.ruled_items
    ADD CONSTRAINT ruled_items_capture_id_fkey FOREIGN KEY (capture_id) REFERENCES staging.captures(id);


ALTER TABLE ONLY telemetry.scraper_runs
    ADD CONSTRAINT scraper_runs_court_id_fkey FOREIGN KEY (court_id) REFERENCES derived.courts(id);



